for(tries=0;tries<140;tries++){
  x=120+rr()*(WORLD_W-240); y=120+rr()*(WORLD_H-240);
  if(Math.hypot(x-p.x,y-p.y)<700) continue;
  if(!fireFits(x,y,FIRE.r,0)) continue;   // v16.xx (firefit): the whole disc on open real ground, not a point

// v16.xx (firefit), HIS ANSWER (2026-10-14): fire hazards "also in random spots, not only from wrecks and events. They must fit the map: on open real ground, never through or on buildings or walls, never on the
// map edges, never on the drop or the rings." The fires were put wherever the middle of the disc was free (a point, 30 of room), so a disc 92 wide could lie across a wall, a building corner or a tree, and burn through
// them on the HUD. A fire now needs its WHOLE DISC to fit (fireFits): every wall of the map, trees and furniture and wrecks too, at least 14 clear of the edge of the disc; the middle not inside a building and not
// in water; no box lying in it; clear of a stronghold; reachable ground; at least 200 inside the map edge (and its edge of border wall); at least 300 from any extraction ring (the debris fires, which land inside a
// ring of their own event, keep 120) and clear of where he dropped. The random fuel fires (two a raid, on their own side stream) look 140 times instead of 60 for such a place. The debris fires of the orbital
// debris event pick their places the same way, so a piece that would land on a wall or a building is moved off it (the event still comes down on the ground it can use).
function fireFits(x,y,r,near){
  var m=G.map, e=200, i, q, c, dx, dy, ws, S=G.flow&&G.flow.fplan?G.flow:null, dr=G.flow&&G.flow.drop;
  if(x<r+e||y<r+e||x>WORLD_W-r-e||y>WORLD_H-r-e) return false;
  if(!navReachable(m,x,y)||shutRoomAt(m,x,y)||buildingAtPt(m,x,y)||inWaterMap(m,x,y)) return false;
  if(flowZoneNear(x,y,near?120:r+300)) return false;
  if(dr&&Math.hypot(x-dr.x,y-dr.y)<r+(near?160:300)) return false;
  ws=wallsNear(G.wgrid,x,y,r+60);
  for(i=0;i<ws.length;i++){ q=ws[i]; dx=Math.max(q.x-x,0,x-(q.x+q.w)); dy=Math.max(q.y-y,0,y-(q.y+q.h)); if(dx*dx+dy*dy<(r+14)*(r+14)) return false; }
  for(i=0;i<G.containers.length;i++){ c=G.containers[i]; if(c&&Math.hypot(c.x-x,c.y-y)<r+8) return false; }
  if(typeof shAt==='function'&&shAt(x,y,r)) return false;
  return true;
}
// FLOW-MODULE-END (the next flow builds add their code above this line)

check:
{v:'VER',what:'firefit, his answer (fire hazards also in random spots, fitting the map): over many seeds every planned fuel fire and every debris fire has its whole disc on open real ground: clear of every wall, not inside a building, not in water, not near the map edge, not on the drop or an extraction ring, and the raid still plans its two fires',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object'||typeof firePlan!=='function'||typeof evLaunch!=='function'||typeof evTick!=='function') return 'SKIP: no arcade, fires or events here';
   var bad=[], g=null, p=null, m=null, seed0, s, i, j, k, plan, f, n=0, hits=0, worst=1e9, w, dx, dy, d, why={}, E, ev, nd=0, ndHit=0, mp, R=FIRE.r, drop;
   function clear(x,y,r){ var q, o=1e9; for(q=0;q<m.walls.length;q++){ w=m.walls[q]; dx=Math.max(w.x-x,0,x-(w.x+w.w)); dy=Math.max(w.y-y,0,y-(w.y+w.h)); d=Math.sqrt(dx*dx+dy*dy)-r; if(d<o) o=d; } return o; }
   function why1(x,y,r,rings){
     var q, z, o=clear(x,y,r), out=[];
     if(o<10) out.push('cuts a wall by '+Math.round(10-o));
     if(x<r+150||y<r+150||x>WORLD_W-r-150||y>WORLD_H-r-150) out.push('is on the map edge');
     if(typeof buildingAtPt==='function'&&buildingAtPt(m,x,y)) out.push('is inside a building');
     if(typeof inWaterMap==='function'&&inWaterMap(m,x,y)) out.push('is in water');
     if(Math.hypot(x-drop.x,y-drop.y)<r+150) out.push('is on the drop');
     for(q=0;q<g.zones.length;q++){ z=g.zones[q]; if(Math.hypot(x-z.x,y-z.y)<(z.r||0)+r+rings) out.push('is on ring '+q); }
     return out;
   }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     for(mp=0;mp<2;mp++){
       if(!arcadeDeploy({mapIx:mp,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
       g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
       p=g.player; m=g.map; drop={x:p.x,y:p.y}; seed0=g.seed; flowS().drop={x:drop.x,y:drop.y};
       // ONE: the fuel fires, over many seeds on this map: two planned, every disc fits
       for(s=1;s<=70;s++){
         g.seed=s; plan=firePlan({});
         if(plan.length<1||plan.length>2) bad.push('ONE: map '+mp+' seed '+s+' planned '+plan.length+' fires');
         for(i=0;i<plan.length;i++){
           f=plan[i]; n++;
           if(Math.hypot(f.x-drop.x,f.y-drop.y)<699) { hits++; why['the drop 700']=(why['the drop 700']|0)+1; continue; }
           j=why1(f.x,f.y,R,250);
           if(j.length){ hits++; for(k=0;k<j.length;k++) why[j[k].replace(/ [0-9]+$/,'')]=(why[j[k].replace(/ [0-9]+$/,'')]|0)+1; }
         }
       }
       g.seed=seed0;
       // TWO: the debris fires: every piece of an orbital debris event lands where its disc of 58 fits
       for(s=1;s<=24;s++){
         g.seed=s*7+mp; E=evS(); E.live=[]; E.plan=[]; E.n=0;
         ev=evLaunch('debris'); if(!ev) continue;
         ev.t=ev.warn; evTick(0.01);
         if(ev.ph!=='live'||!ev.d.pts) continue;
         for(i=0;i<ev.d.pts.length;i++){ nd++; j=why1(ev.d.pts[i].x,ev.d.pts[i].y,58,60); if(j.length){ ndHit++; for(k=0;k<j.length;k++) why['debris '+j[k].replace(/ [0-9]+$/,'')]=(why['debris '+j[k].replace(/ [0-9]+$/,'')]|0)+1; } }
       }
       g.seed=seed0; E=evS(); E.live=[]; E.n=0;
       try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
       try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
       __topClear(); __runPrep();
     }
     if(n<130) bad.push('ONE: only '+n+' fires were planned in 140 raids');
     if(hits) bad.push('ONE: '+hits+' of '+n+' planned fires do not fit the map ('+JSON.stringify(why)+')');
     if(nd<30) bad.push('TWO: only '+nd+' pieces of debris came down in 48 events');
     if(ndHit) bad.push('TWO: '+ndHit+' of '+nd+' debris fires do not fit the map ('+JSON.stringify(why)+')');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     try{ if(g&&seed0!==undefined) g.seed=seed0; }catch(_s){}
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ if(typeof ARCADE==='object'){ ARCADE.mine=0; ARCADE.waveT=0; ARCADE.holdT=0; } }catch(_h){}
     __topClear();
   }
   return bad.length?bad.slice(0,8).join('; '):null; }},
